ALTER TABLE public.listings ADD COLUMN readiness_data jsonb NOT NULL DEFAULT '{}'::jsonb, ADD COLUMN readiness_status text NOT NULL DEFAULT 'not_started', ADD COLUMN readiness_submitted_at timestamptz;
CREATE TABLE public.corrective_action_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), action_id uuid NOT NULL REFERENCES public.corrective_actions(id), actor_id uuid NOT NULL DEFAULT auth.uid(), event_type text NOT NULL CHECK(event_type IN ('response','appeal','closed','reopened')), note text NOT NULL CHECK(length(note) BETWEEN 10 AND 2000), evidence_ids uuid[] NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.corrective_action_events TO authenticated;
GRANT ALL ON public.corrective_action_events TO service_role;
ALTER TABLE public.corrective_action_events ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.is_assurance_staff(_uid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(auth.jwt()->>'aal','')='aal2' AND EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_uid AND role IN ('admin','reviewer')) $$;
CREATE POLICY "action history read" ON public.corrective_action_events FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.corrective_actions c WHERE c.id=action_id AND (public.owns_listing(c.listing_id,auth.uid()) OR public.is_assurance_staff(auth.uid()))));
CREATE POLICY "action history response" ON public.corrective_action_events FOR INSERT TO authenticated WITH CHECK(actor_id=auth.uid() AND event_type IN ('response','appeal') AND EXISTS(SELECT 1 FROM public.corrective_actions c WHERE c.id=action_id AND public.owns_listing(c.listing_id,auth.uid())));
CREATE POLICY "action history staff" ON public.corrective_action_events FOR INSERT TO authenticated WITH CHECK(actor_id=auth.uid() AND public.is_assurance_staff(auth.uid()));
CREATE POLICY "reviewer listing read" ON public.listings FOR SELECT TO authenticated USING(public.is_assurance_staff(auth.uid()));
CREATE POLICY "phase2 audit mfa" ON public.audits AS RESTRICTIVE FOR ALL TO authenticated USING(public.owns_listing(listing_id,auth.uid()) OR auth.jwt()->>'aal'='aal2') WITH CHECK(auth.jwt()->>'aal'='aal2');
CREATE POLICY "phase2 response mfa" ON public.audit_responses AS RESTRICTIVE FOR ALL TO authenticated USING(EXISTS(SELECT 1 FROM public.audits a WHERE a.id=audit_id AND (public.owns_listing(a.listing_id,auth.uid()) OR auth.jwt()->>'aal'='aal2'))) WITH CHECK(auth.jwt()->>'aal'='aal2');
CREATE OR REPLACE FUNCTION public.guard_phase2_listing() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='INSERT' THEN NEW.readiness_status='draft'; NEW.assurance_state='not_checked'; ELSIF NOT public.is_assurance_staff(auth.uid()) THEN NEW.assurance_state=OLD.assurance_state; NEW.last_audited_at=OLD.last_audited_at; NEW.next_review_at=OLD.next_review_at; IF NEW.readiness_status='approved' THEN NEW.readiness_status=OLD.readiness_status; END IF; END IF; IF NEW.status='approved' AND NEW.readiness_status<>'not_started' AND NEW.readiness_status<>'approved' THEN RAISE EXCEPTION 'Readiness approval required before publication'; END IF; RETURN NEW; END $$;
CREATE TRIGGER phase2_listing_guard BEFORE INSERT OR UPDATE ON public.listings FOR EACH ROW EXECUTE FUNCTION public.guard_phase2_listing();
CREATE OR REPLACE FUNCTION public.save_readiness(_listing uuid,_data jsonb,_submit boolean DEFAULT false) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR NOT public.owns_listing(_listing,auth.uid()) THEN RAISE EXCEPTION 'Forbidden'; END IF; IF jsonb_typeof(_data)<>'object' OR length(_data::text)>12000 THEN RAISE EXCEPTION 'Invalid readiness data'; END IF; IF _submit AND (length(coalesce(_data->>'mandate',''))<10 OR length(coalesce(_data->>'utilities',''))<10 OR length(coalesce(_data->>'safety',''))<10 OR coalesce(_data->>'capacity','') !~ '^[1-9][0-9]{0,4}$') THEN RAISE EXCEPTION 'Complete authority, capacity, utilities and safety disclosures'; END IF; UPDATE public.listings SET readiness_data=_data,readiness_status=CASE WHEN _submit THEN 'submitted' ELSE 'draft' END,readiness_submitted_at=CASE WHEN _submit THEN now() ELSE NULL END,status='pending' WHERE id=_listing; END $$;
REVOKE ALL ON FUNCTION public.save_readiness(uuid,jsonb,boolean) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.save_readiness(uuid,jsonb,boolean) TO authenticated;
CREATE OR REPLACE FUNCTION public.respond_corrective_action(_action uuid,_note text,_appeal boolean,_evidence uuid[] DEFAULT '{}') RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE lid uuid; BEGIN SELECT listing_id INTO lid FROM public.corrective_actions WHERE id=_action; IF NOT public.owns_listing(lid,auth.uid()) OR length(trim(_note)) NOT BETWEEN 10 AND 2000 THEN RAISE EXCEPTION 'Forbidden or invalid response'; END IF; IF EXISTS(SELECT 1 FROM unnest(_evidence) e WHERE NOT EXISTS(SELECT 1 FROM public.evidence_documents d WHERE d.id=e AND d.listing_id=lid)) THEN RAISE EXCEPTION 'Invalid evidence'; END IF; INSERT INTO public.corrective_action_events(action_id,event_type,note,evidence_ids) VALUES(_action,CASE WHEN _appeal THEN 'appeal' ELSE 'response' END,trim(_note),_evidence); UPDATE public.corrective_actions SET provider_response=trim(_note),status=CASE WHEN _appeal THEN 'appealed' ELSE 'resolution_submitted' END,submitted_resolution_at=now(),updated_at=now() WHERE id=_action; END $$;
REVOKE ALL ON FUNCTION public.respond_corrective_action(uuid,text,boolean,uuid[]) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.respond_corrective_action(uuid,text,boolean,uuid[]) TO authenticated;
CREATE OR REPLACE FUNCTION public.guard_phase2_audit() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.decision IS NOT NULL AND (NEW.auditor_id=auth.uid() OR NOT public.is_assurance_staff(auth.uid()) OR NEW.reviewer_id IS DISTINCT FROM auth.uid() OR length(coalesce(NEW.decision_reason,''))<10) THEN RAISE EXCEPTION 'Independent MFA reviewer and reason required'; END IF; IF TG_OP='UPDATE' AND NOT public.is_assurance_staff(auth.uid()) AND (NEW.listing_id IS DISTINCT FROM OLD.listing_id OR NEW.template_id IS DISTINCT FROM OLD.template_id OR NEW.template_version IS DISTINCT FROM OLD.template_version OR NEW.auditor_id IS DISTINCT FROM OLD.auditor_id OR NEW.reviewer_id IS DISTINCT FROM OLD.reviewer_id OR NEW.status NOT IN ('in_progress','submitted')) THEN RAISE EXCEPTION 'Auditors may only capture and submit assigned inspections'; END IF; IF NEW.status='submitted' AND (TG_OP='INSERT' OR OLD.status IS DISTINCT FROM 'submitted') THEN IF EXISTS(SELECT 1 FROM public.audit_template_items i WHERE i.template_id=NEW.template_id AND NOT EXISTS(SELECT 1 FROM public.audit_responses r WHERE r.audit_id=NEW.id AND r.template_item_id=i.id)) THEN RAISE EXCEPTION 'Complete every checklist item'; END IF; NEW.submitted_at=now(); NEW.server_received_at=now(); END IF; RETURN NEW; END $$;
CREATE TRIGGER phase2_audit_guard BEFORE INSERT OR UPDATE ON public.audits FOR EACH ROW EXECUTE FUNCTION public.guard_phase2_audit();
CREATE OR REPLACE FUNCTION public.guard_phase2_evidence() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='INSERT' THEN NEW.scan_status='pending'; NEW.review_status='pending'; NEW.access_class='restricted'; NEW.uploaded_by=auth.uid(); IF public.evidence_path_listing(NEW.storage_key) IS DISTINCT FROM NEW.listing_id THEN RAISE EXCEPTION 'Evidence path mismatch'; END IF; ELSIF NEW.review_status='approved' AND NEW.scan_status<>'clean' THEN RAISE EXCEPTION 'Virus scanning required'; END IF; RETURN NEW; END $$;
CREATE TRIGGER phase2_evidence_guard BEFORE INSERT OR UPDATE ON public.evidence_documents FOR EACH ROW EXECUTE FUNCTION public.guard_phase2_evidence();
CREATE POLICY "quarantined evidence" ON storage.objects AS RESTRICTIVE FOR SELECT TO authenticated USING(bucket_id<>'evidence' OR EXISTS(SELECT 1 FROM public.evidence_documents d WHERE d.storage_key=name AND d.scan_status='clean'));
CREATE OR REPLACE FUNCTION public.review_readiness(_listing uuid,_approve boolean,_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_assurance_staff(auth.uid()) OR public.owns_listing(_listing,auth.uid()) OR length(trim(_reason)) NOT BETWEEN 10 AND 2000 THEN RAISE EXCEPTION 'Independent MFA reviewer and reason required'; END IF; IF _approve AND (NOT EXISTS(SELECT 1 FROM public.audits WHERE listing_id=_listing AND decision='approved') OR EXISTS(SELECT 1 FROM public.corrective_actions WHERE listing_id=_listing AND status<>'closed') OR NOT EXISTS(SELECT 1 FROM public.evidence_documents WHERE listing_id=_listing AND review_status='approved' AND scan_status='clean' AND (expires_at IS NULL OR expires_at>=current_date))) THEN RAISE EXCEPTION 'Approved audit, current checked evidence and closed actions required'; END IF; UPDATE public.listings SET readiness_status=CASE WHEN _approve THEN 'approved' ELSE 'information_requested' END WHERE id=_listing; INSERT INTO public.audit_log(actor_id,resource_type,resource_id,action,after_data) VALUES(auth.uid(),'listings',_listing,'readiness_review',jsonb_build_object('approved',_approve,'reason',_reason)); END $$;
REVOKE ALL ON FUNCTION public.review_readiness(uuid,boolean,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.review_readiness(uuid,boolean,text) TO authenticated;